    const sub = a => (a.q3 != null ? `${L(d.revTag)}: ${revFmt(a, "q3", a.q3 < 15 ? 3 : 1)}` : T(`full year ${L(d.revTag)}`,`ano de ${L(d.revTag)}`)) + (revRep(a) != null ? T(" · as reported"," · divulgado") : "");
    const facts = isQ3
