  function renderSlide() {
    clearTimers(); const s = SLIDES[slideIdx]();
    slide.className = "slide" + (s.cls ? " " + s.cls : ""); slide.innerHTML = s.html; slide.scrollTop = 0;
    void slide.offsetWidth; slide.classList.add("enter");
    $("deck-count").textContent = (slideIdx + 1) + " / " + SLIDES.length;
    $("deck-prog").style.width = (100 * (slideIdx + 1) / SLIDES.length) + "%";
    $("deck-prev").disabled = slideIdx === 0; $("deck-next").disabled = slideIdx === SLIDES.length - 1;
    [...$("deck-dots").children].forEach((d, i) => d.setAttribute("aria-current", String(i === slideIdx)));
    if (s.mount) s.mount(slide);
  }
  $("deck-dots").innerHTML = SLIDES.map((_, i) => `<button aria-label="Slide ${i + 1}"></button>`).join("");
  [...$("deck-dots").children].forEach((d, i) => d.onclick = () => { slideIdx = i; renderSlide(); });
  function openDeck(i = 0) { setPlaying(false); lastFocus = document.activeElement; slideIdx = i; deck.hidden = false; syncBodyLock(); renderSlide(); deck.focus(); }
  function closeDeck() { clearTimers(); deck.hidden = true; syncBodyLock(); if (lastFocus) lastFocus.focus(); }
  $("openDeck").onclick = () => openDeck(0); $("pipeDeck").onclick = () => openDeck(0); $("openDeckFooter").onclick = () => openDeck(0);
  $("deck-close").onclick = closeDeck;
  $("deck-prev").onclick = () => { if (slideIdx > 0) { slideIdx--; renderSlide(); } };
  $("deck-next").onclick = () => { if (slideIdx < SLIDES.length - 1) { slideIdx++; renderSlide(); } };
  $("deckStage").addEventListener("click", e => { if (e.target === $("deckStage")) closeDeck(); });
  let touchX = null;
  slide.addEventListener("touchstart", e => { touchX = e.touches[0].clientX; }, {passive:true});
  slide.addEventListener("touchend", e => { if (touchX === null) return; const dx = e.changedTouches[0].clientX - touchX; touchX = null; if (Math.abs(dx) > 55) (dx < 0 ? $("deck-next") : $("deck-prev")).click(); }, {passive:true});

